resolveBooleanEvaluation(
  flagKey: string,
  defaultValue: boolean,
  context: EvaluationContext,
): Promise<ResolutionDetails<boolean>> {
  return this.flagResolutionProxy<boolean>(flagKey, 'boolean', defaultValue, context);
}

const tasks: Promise<[boolean, BaseProviderResolutionResult<T, ProviderStatus, Provider> | null]>[] = [];

for (const providerEntry of this.providerEntries) {
  const task = this.evaluateProviderEntry(
    flagKey,
    flagType,
    defaultValue,
    providerEntry,
    hookContext,
    hookHints,
    context,
  );

  tasks.push(task);

  if (this.evaluationStrategy.runMode === 'sequential') {
    const [shouldEvaluateNext] = await task;
    if (!shouldEvaluateNext) {
      break;
    }
  }
}

const results = await Promise.all(tasks);
const resolutions = results
  .map(([, resolution]) => resolution)
  .filter((r): r is BaseProviderResolutionResult<T, ProviderStatus, Provider> => Boolean(r));

const finalResult = this.evaluationStrategy.determineFinalResult({ flagKey, flagType }, context, resolutions);

private async callProviderResolve<T extends boolean | string | number | JsonValue>(
  provider: Provider,
  flagKey: string,
  defaultValue: T,
  context: EvaluationContext,
) {
  switch (typeof defaultValue) {
    case 'string':
      return await provider.resolveStringEvaluation(flagKey, defaultValue, context, this.logger);
    case 'number':
      return await provider.resolveNumberEvaluation(flagKey, defaultValue, context, this.logger);
    case 'object':
      return await provider.resolveObjectEvaluation(flagKey, defaultValue, context, this.logger);
    case 'boolean':
      return await provider.resolveBooleanEvaluation(flagKey, defaultValue, context, this.logger);

export class FirstMatchStrategy<TProviderStatus, TProvider> extends BaseEvaluationStrategy<TProviderStatus, TProvider> {
  override shouldEvaluateNextProvider<T extends FlagValue>(
    strategyContext: BaseStrategyPerProviderContext<TProviderStatus, TProvider>,
    context: EvaluationContext,
    result: BaseProviderResolutionResult<T, TProviderStatus, TProvider>,
  ): boolean {
    if (this.hasErrorWithCode(result, ErrorCode.FLAG_NOT_FOUND)) {
      return true;
    }
    if (this.hasError(result)) {
      return false;
    }
    return false;
  }

  override determineFinalResult<T extends FlagValue>(
    strategyContext: BaseStrategyPerProviderContext<TProviderStatus, TProvider>,
    context: EvaluationContext,
    resolutions: BaseProviderResolutionResult<T, TProviderStatus, TProvider>[],
  ): BaseFinalResult<T, TProviderStatus, TProvider> {
    const finalResolution = resolutions[resolutions.length - 1];
    if (this.hasError(finalResolution)) {
      return this.collectProviderErrors(resolutions);
    }
    return this.resolutionToFinalResult(finalResolution);

